class Solution:
    def repeatWithinReach(self, codes: List[int], k: int) -> bool:
        n = len(codes)
        for i in range(n):
            for j in range(i + 1, min(n, i + k + 1)):
                if codes[j] == codes[i]:
                    return True
        return False

