class Solution {
    public boolean repeatWithinReach(int[] codes, int k) {
        int n = codes.length;
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n && j <= i + k; j++)
                if (codes[j] == codes[i]) return true;
        return false;
    }
}

