class Solution:
    def repeatWithinReach(self, codes: List[int], k: int) -> bool:
        order = sorted(range(len(codes)), key=lambda i: (codes[i], i))
        for a, b in zip(order, order[1:]):
            if codes[a] == codes[b] and b - a <= k:
                return True
        return False

