class Solution {
    public boolean repeatWithinReach(int[] codes, int k) {
        int n = codes.length;
        long[] keyed = new long[n];
        for (int i = 0; i < n; i++) keyed[i] = ((long) codes[i] << 20) | i;
        Arrays.sort(keyed);
        for (int t = 1; t < n; t++) {
            long a = keyed[t - 1], b = keyed[t];
            if ((a >> 20) == (b >> 20) && (b & 0xFFFFF) - (a & 0xFFFFF) <= k) return true;
        }
        return false;
    }
}

