static int by_code(const void* x, const void* y) {
    const int* a = x;
    const int* b = y;
    if (a[0] != b[0]) return a[0] < b[0] ? -1 : 1;
    return a[1] - b[1];
}

bool repeatWithinReach(int* codes, int codesSize, int k) {
    int n = codesSize;
    int* keyed = malloc(2 * n * sizeof(int));
    for (int i = 0; i < n; i++) { keyed[2 * i] = codes[i]; keyed[2 * i + 1] = i; }
    qsort(keyed, n, 2 * sizeof(int), by_code);
    bool found = false;
    for (int t = 1; t < n && !found; t++)
        if (keyed[2 * t] == keyed[2 * t - 2] && keyed[2 * t + 1] - keyed[2 * t - 1] <= k) found = true;
    free(keyed);
    return found;
}

