class Solution {
    public boolean repeatWithinReach(int[] codes, int k) {
        Map<Integer, Integer> last = new HashMap<>();
        for (int i = 0; i < codes.length; i++) {
            Integer prev = last.put(codes[i], i);
            if (prev != null && i - prev <= k) return true;
        }
        return false;
    }
}

