bool repeatWithinReach(int* codes, int codesSize, int k) {
    int cap = 1;
    while (cap < 2 * codesSize) cap <<= 1;
    int* keys = malloc(cap * sizeof(int));
    int* at = malloc(cap * sizeof(int));
    char* used = calloc(cap, 1);
    bool found = false;
    for (int i = 0; i < codesSize && !found; i++) {
        unsigned h = ((unsigned) codes[i] * 2654435761u) & (cap - 1);
        while (used[h] && keys[h] != codes[i]) h = (h + 1) & (cap - 1);
        if (used[h] && i - at[h] <= k) found = true;
        used[h] = 1;
        keys[h] = codes[i];
        at[h] = i;
    }
    free(keys); free(at); free(used);
    return found;
}
